function dijkstra(graph, start){
  var dist={}, prev={}, Q={};
  for(var n in graph){ if(!(n in dist)){ dist[n]=Infinity; Q[n]=true; } }
  for(var n2 in graph){ var es=graph[n2]; for(var i=0;i<es.length;i++){ var v=es[i][0]; if(!(v in dist)){ dist[v]=Infinity; Q[v]=true; } } }
  if(!(start in dist)){ dist[start]=0; Q[start]=true; }
  else { dist[start]=0; }
  while(true){
    var u=null, best=Infinity;
    for(var k in Q){ if(dist[k]<best){ best=dist[k]; u=k; } }
    if(u===null) break;
    delete Q[u];
    var edges = graph[u] || [];
    for(var i=0;i<edges.length;i++){
      var v=edges[i][0], w=edges[i][1];
      var dv = (dist[v]===undefined ? Infinity : dist[v]);
      if(dist[u]+w < dv){ dist[v]=dist[u]+w; prev[v]=u; }
    }
  }
  return {dist:dist, prev:prev};
}
function dijkstraPath(result, start, target){
  if(result.dist[target]===undefined || result.dist[target]===Infinity) return null;
  var path=[], cur=target;
  while(cur!==undefined){
    path.unshift(cur);
    if(cur===start) break;
    cur=result.prev[cur];
  }
  return path;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dijkstra:dijkstra, dijkstraPath:dijkstraPath };
}
if (typeof window !== 'undefined') {
  window.DijkstraForgePure = { dijkstra:dijkstra, dijkstraPath:dijkstraPath };
}
